-- Function: public.fn_get_active_staff_leaves
-- Backup generated on 2026-10-25 20:32:58

CREATE OR REPLACE FUNCTION public.fn_get_active_staff_leaves(p_tenant_id uuid, p_date date)  RETURNS TABLE(id uuid, teacher_id uuid, leave_type character varying, start_date date, end_date date, reason character varying, status character varying, coverage_status character varying, substitute_teacher_id uuid, teacher_name character varying, substitute_teacher_name character varying)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT sl.id, sl.teacher_id, sl.leave_type::VARCHAR, sl.start_date, sl.end_date, sl.reason::VARCHAR,            sl.status::VARCHAR, sl.coverage_status::VARCHAR, sl.substitute_teacher_id,            (t.first_name || ' ' || t.last_name)::VARCHAR AS teacher_name,            (sub.first_name || ' ' || sub.last_name)::VARCHAR AS substitute_teacher_name     FROM staff_leaves sl     JOIN teachers t ON sl.teacher_id = t.id     LEFT JOIN teachers sub ON sl.substitute_teacher_id = sub.id     WHERE sl.tenant_id = p_tenant_id       AND sl.start_date <= p_date AND sl.end_date >= p_date       AND sl.status != 'Cancelled' AND sl.status != 'Rejected'     ORDER BY sl.start_date DESC; END; $function$ ;
